/* CHECKBOX */

.check {
  display: -webkit-flex;
  display: flex;
  -webkit-align-items: flex-end;
  align-items: flex-end;
}

.check__input {
  width: 1px;
  height: 1px;
  padding: 0;
  border: 0;
  margin: -1px;
  clip: rect(0, 0, 0, 0);
  overflow: hidden;
  position: absolute;
}

.check__element {
  cursor: pointer;
  vertical-align: middle;
  display: inline-block;
  position: relative;
  border: 2px solid #fff;
  width: 22px;
  height: 22px;
}

.check__element:before {
  font: bold 1.6em/0.8em verdana, arial, sans-serif;
  content: "\00d7";
  display: none;
  position: absolute;
  top: 0px;
  left: 0px;
  width: 100%;
  height: 100%;
  text-align: center;
  transition: -webkit-transform 0.28s cubic-bezier(0.4, 0, 0.2, 1);
  transition: transform 0.28s cubic-bezier(0.4, 0, 0.2, 1);
  transition: transform 0.28s cubic-bezier(0.4, 0, 0.2, 1), -webkit-transform 0.28s cubic-bezier(0.4, 0, 0.2, 1);
}

.check__label {
  padding-left: 10px;
  cursor: pointer;
  vertical-align: middle;
}

.check__input:checked + .check__element:before {
  display: block;
  font-size: 1.2em;
}

/* RADIO BUTTONS */

.radio {
  display: inline-block;
  position: relative;
  margin: 0;
  font-size: 1em;
  line-height: 24px;
  width: 50%;
}

.radio__input {
  position: absolute;
  top: 0;
  left: 0;
  width: 40px;
  height: 45px;
  opacity: 0;
  z-index: 2;
  cursor: pointer;
}

.radio__label {
  display: block;
  padding: 10px 10px 10px 24px;
  cursor: pointer;
  font-size: 1em;
}

.radio__label:before {
  background: transparent;
  content: "";
  position: absolute;
  top: 12px;
  left: 0;
  width: 22px;
  height: 22px;
  border: 2px solid #fff;
  border-radius: 14px;
  z-index: 1;
  transition: border-color 0.28s cubic-bezier(0.4, 0, 0.2, 1);
}

.radio__label:after {
  background: #fff;
  content: "";
  position: absolute;
  top: 16px;
  left: 4px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  z-index: 2;
  -webkit-transform: scale(0, 0);
  transform: scale(0, 0);
  transition: -webkit-transform 0.28s cubic-bezier(0.4, 0, 0.2, 1);
  transition: transform 0.28s cubic-bezier(0.4, 0, 0.2, 1);
  transition: transform 0.28s cubic-bezier(0.4, 0, 0.2, 1), -webkit-transform 0.28s cubic-bezier(0.4, 0, 0.2, 1);
}

.radio .radio--repeat:last-child {
  display: block;
}

.radio__input:checked + .radio__label:before {
  border-color: #fff;
}

.radio__input:checked + .radio__label:after {
  -webkit-transform: scale(1, 1);
  transform: scale(1, 1);
}

.radio__input[disabled="disabled"] + .radio__label {
  opacity: 0.4;
}

.rzslider .rz-pointer.rz-active:after {
  background: #fff !important;
}

