.border {
  position: relative;
}

.border:after {
  content: '';
  border-color: #000;
  display: block;
  width: 100%;
  height: 100%;
  position: absolute;
  top: 0;
  left: 0;
}

.border--top:after {
  border-top-style: solid;
}

.border--bottom:after {
  border-bottom-style: solid;
}

.border--left:after {
  border-left-style: solid;
}

.border--right:after {
  border-right-style: solid;
}

.border--thin:after {
  border-width: 0.3mm;
}

.border--thick:after {
  border-width: 0.6mm;
}

.border--outside:after {
  width: calc(100% + 1.7mm);
  height: calc(100% + 1.7mm);
  top: calc(1.7mm / -2);
  left: calc(1.7mm / -2);
}

.border--outside.border--thin:after {
  width: calc(100% + 1.1mm);
  height: calc(100% + 1.1mm);
  top: calc(1.1mm / -2);
  left: calc(1.1mm / -2);
}

.border--middle:after {
  border-width: 1mm;
  width: calc(100% + 1.6mm);
  height: calc(100% + 1.6mm);
  top: calc(1.6mm / -2);
  left: calc(1.6mm / -2);
}

.border--red:after {
  border-color: red;
}

.border--period:after {
  content: '';
  bottom: -2px;
  left: 0;
  top: auto;
  border-bottom-width: 3px;
  border-bottom-style: solid;
